                result.append((start, i - 1))
                start = None
        return result

    rb = bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))

    tiles = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            # Incomplete cropped tiles are not objects.
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            interior = [
                grid[r][c]
                for r in range(r0 + 1, r1)
                for c in range(c0 + 1, c1)
                if grid[r][c] != 0
            ]
            if not interior:
                continue
            freq = {}
            for color in interior:
                freq[color] = freq.get(color, 0) + 1
            color = max(freq, key=freq.get)
            tiles[(ri, ci)] = (color, r0, r1, c0, c1)

    out = [row[:] for row in grid]

